"""Read-only summaries of workflow routine and schedule tables."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re
import sys

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}


def reject_constant(value):
    raise ValueError("non-finite JSON number: " + value)


def read_table(folder, table):
    try:
        with (folder / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError, RecursionError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(column, str) for column in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp.replace(tzinfo=now.tzinfo) if stamp.tzinfo is None else stamp


def routine(row, now):
    every = row["every"]
    if EVERY.fullmatch(every) is None:
        raise ValueError("invalid interval")
    last = row["last_time"]
    stamp = timestamp(last, now) if last else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid exit code")
    next_stamp = None
    if stamp is not None and every[-1] != "r":
        next_stamp = stamp + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
    if code == "running":
        state = "running"
    elif stamp is None:
        state = "never"
    elif code is not None and code != 0:
        state = "failed"
    elif next_stamp is not None and now >= next_stamp:
        state = "overdue"
    else:
        state = "ok"
    rendered = (next_stamp.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                if next_stamp is not None else None)
    return {"name": row["name"], "every": every, "last_time": last or None,
            "last_code": code, "state": state, "next": rendered}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def valid_rows(table, rows, now, bad):
    seen = set()
    result = []
    for index, row in enumerate(rows):
        name = row.get("name") if isinstance(row, dict) else None
        if isinstance(name, str) and name:
            if name in seen:
                bad.append({"table": table, "row": index, "why": "dup_name"})
                continue
            seen.add(name)
        if (not isinstance(row, dict) or not isinstance(name, str) or not name
                or not all(key in row for key in REQUIRED[table])
                or not all(isinstance(value, str) for value in row.values())):
            bad.append({"table": table, "row": index, "why": "bad_row"})
            continue
        try:
            item = routine(row, now) if table == "routines" else scheduled(row, now)
        except (ValueError, OverflowError):
            bad.append({"table": table, "row": index, "why": "bad_row"})
            continue
        result.append(item)
    return sorted(result, key=lambda item: item["name"])


def summarize(folder, now):
    bad = []
    output = {"v": 1}
    counts = {"routines": {state: 0 for state in
                           ("running", "never", "failed", "overdue", "ok")},
              "schedule": {state: 0 for state in ("interrupted", "due", "pending")}}
    for table in ("routines", "schedule"):
        rows, errors = read_table(folder, table)
        bad.extend(errors)
        output[table] = valid_rows(table, rows, now, bad)
        for item in output[table]:
            counts[table][item["state"]] += 1
    output["counts"] = counts
    output["bad"] = sorted(bad, key=lambda item:
                           (item["table"], -1 if item["row"] is None else item["row"],
                            item["why"]))
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables without writing")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
